  UNIQUE KEY `uq_funding_disbursement_agreement_id_reference` (`tenant_id`, `agreement_id`, `reference`),
  KEY `ix_funding_disbursement_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_funding_disbursement_budget_line_id` (`tenant_id`, `budget_line_id`),
  KEY `ix_funding_disbursement_capital_plan_item_id` (`tenant_id`, `capital_plan_item_id`),
  CONSTRAINT `ck_funding_disbursement__payee_kind` CHECK (`payee_kind` IN ('institution', 'beneficiary', 'supplier', 'contractor')),
  CONSTRAINT `ck_funding_disbursement__status` CHECK (`status` IN ('scheduled', 'paid', 'failed', 'reversed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FND/transaction/restricted] Disbursement of an agreement to the institution, the beneficiary, a supplier or a contractor';

CREATE TABLE `funding_programme` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `code` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `provider_name` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `provider_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `provider_body_code` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Education body in the regulators'' directory, e.g. TETFUND, UBEC, NELFUND',
  `beneficiary_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `purpose` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `instrument` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `interest_rate` DECIMAL(6,3) NOT NULL DEFAULT 0 COMMENT 'Annual nominal rate; 0 for interest-free loans and for grants',
  `tenor_months` SMALLINT,
  `moratorium_months` SMALLINT NOT NULL DEFAULT 0,
  `repayment_basis` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `max_amount_minor` BIGINT COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `eligibility` JSON COMMENT 'Rules: beneficiary levels, ownership, category, minimum service years, maximum income, matching contribution …',
  `terms` JSON COMMENT 'Further terms as published (e.g. repayment as a share of salary after national service)',
  `opens_on` DATE,
  `closes_on` DATE,
  `data_status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_funding_programme_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_funding_programme_scope_node_id_code` (`tenant_id`, `scope_node_id`, `code`),
  CONSTRAINT `ck_funding_programme__provider_kind` CHECK (`provider_kind` IN ('federal_government_agency', 'state_government', 'local_government', 'development_partner', 'bank', 'microfinance', 'cooperative', 'employer', 'institution', 'alumni', 'philanthropy', 'other')),
  CONSTRAINT `ck_funding_programme__beneficiary_kind` CHECK (`beneficiary_kind` IN ('institution', 'staff', 'learner')),
  CONSTRAINT `ck_funding_programme__purpose` CHECK (`purpose` IN ('capital_works', 'equipment', 'ict', 'research', 'staff_development', 'operations', 'tuition_fees', 'upkeep', 'housing', 'vehicle', 'welfare_emergency', 'salary_advance', 'scholarship', 'bursary', 'special_needs', 'other')),
  CONSTRAINT `ck_funding_programme__instrument` CHECK (`instrument` IN ('loan', 'grant', 'scholarship', 'bursary', 'intervention', 'matching_grant', 'salary_advance', 'bond', 'guarantee', 'in_kind')),
  CONSTRAINT `ck_funding_programme__repayment_basis` CHECK (`repayment_basis` IN ('none', 'fixed_instalment', 'annuity', 'income_contingent', 'payroll_deduction', 'bullet')),
  CONSTRAINT `ck_funding_programme__data_status` CHECK (`data_status` IN ('verified', 'illustrative', 'to_confirm')),
  CONSTRAINT `ck_funding_programme__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FND/config/internal] Funding or loan programme — provider, beneficiary, purpose, instrument, terms and eligibility';

CREATE TABLE `funding_repayment` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `agreement_id` BINARY(16) NOT NULL,
  `amount_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `method` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source_kind` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'payroll_run, bank_statement_line, remittance',
  `source_id` BINARY(16),
  `reference` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `received_on` DATE NOT NULL,
  `allocations` JSON NOT NULL COMMENT 'Instalment sequence → amount',
  `recorded_by` BINARY(16) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_funding_repayment_agreement_id_reference` (`tenant_id`, `agreement_id`, `reference`),
  CONSTRAINT `ck_funding_repayment__method` CHECK (`method` IN ('payroll_deduction', 'direct_debit', 'bank_transfer', 'employer_remittance', 'cash', 'offset'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FND/event/restricted] Repayment received (payroll deduction, direct debit, transfer, employer remittance) and its allocation to instalments';

CREATE TABLE `repayment_instalment` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `agreement_id` BINARY(16) NOT NULL,
  `sequence` SMALLINT NOT NULL,
  `due_on` DATE NOT NULL,
  `principal_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `interest_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `paid_minor` BIGINT NOT NULL DEFAULT 0 COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `paid_on` DATE,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_repayment_instalment_agreement_id_sequence` (`tenant_id`, `agreement_id`, `sequence`),
  KEY `ix_repayment_instalment_due_on_status` (`tenant_id`, `due_on`, `status`),
  CONSTRAINT `ck_repayment_instalment__status` CHECK (`status` IN ('due', 'partly_paid', 'paid', 'overdue', 'waived')),
  CONSTRAINT `ck_repayment_instalment__paid_within` CHECK (paid_minor <= principal_minor + interest_minor)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FND/transaction/restricted] Instalment of a repayment schedule — principal, interest, amount paid and status';

CREATE TABLE `facility_action` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `rule` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `subject_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `subject_id` BINARY(16) NOT NULL,
  `dedupe_key` VARCHAR(120) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'rule:subject while open; suffixed with the action id when closed',
  `title` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `detail` TEXT,
  `priority` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `owner_role` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `due_on` DATE NOT NULL,
  `escalation_level` SMALLINT NOT NULL DEFAULT 0 COMMENT '0 institution, 1 LGA, 2 ministry',
  `escalated_at` DATETIME(6),
  `maintenance_request_id` BINARY(16),
  `resolved_by` BINARY(16),
  `resolved_at` DATETIME(6),
  `resolution` TEXT,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_facility_action_dedupe_key` (`tenant_id`, `dedupe_key`),
  KEY `ix_facility_action_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_facility_action_institution_id_status` (`tenant_id`, `institution_id`, `status`),
  KEY `ix_facility_action_status_due_on` (`tenant_id`, `status`, `due_on`),
  KEY `ix_facility_action_maintenance_request_id` (`tenant_id`, `maintenance_request_id`),
  CONSTRAINT `ck_facility_action__rule` CHECK (`rule` IN ('unsafe_in_use', 'assessment_overdue', 'never_assessed', 'maintenance_due', 'maintenance_overdue', 'condition_deteriorated', 'safety_check_overdue', 'predicted_failure', 'encroachment', 'no_title')),
  CONSTRAINT `ck_facility_action__subject_kind` CHECK (`subject_kind` IN ('site', 'building', 'room', 'asset')),
  CONSTRAINT `ck_facility_action__priority` CHECK (`priority` IN ('critical', 'high', 'moderate', 'info')),
  CONSTRAINT `ck_facility_action__status` CHECK (`status` IN ('open', 'acknowledged', 'in_progress', 'done', 'dismissed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[EST/transaction/internal] Proactive action proposed to the head of institution, with owner, due date and escalation to the LGA and ministry';

CREATE TABLE `facility_assessment` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `subject_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `subject_id` BINARY(16) NOT NULL,
  `assessed_on` DATE NOT NULL,
  `assessor_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `assessed_by` BINARY(16) NOT NULL,
  `condition_grade` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `usability` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `structural_risk` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `defects` JSON COMMENT 'Element (roof, walls, floor, doors, windows, wiring, plumbing …), defect and severity',
  `utilities` JSON COMMENT 'Water, power, sanitation and internet working at the time',
  `in_use` BOOLEAN NOT NULL COMMENT 'Whether the facility is being used at the time of assessment',
  `learners_affected` INT UNSIGNED,
  `repair_estimate_minor` BIGINT COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin,
  `photo_document_ids` JSON,
  `next_due_on` DATE COMMENT 'When it should be assessed again',
  `client_op_id` BINARY(16) COMMENT 'Offline capture (idempotent)',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_facility_assessment_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_facility_assessment_subject_kind_subject_id_assessed_on` (`tenant_id`, `subject_kind`, `subject_id`, `assessed_on`),
  KEY `ix_facility_assessment_institution_id_assessed_on` (`tenant_id`, `institution_id`, `assessed_on`),
  CONSTRAINT `ck_facility_assessment__subject_kind` CHECK (`subject_kind` IN ('site', 'building', 'room', 'asset')),
  CONSTRAINT `ck_facility_assessment__assessor_kind` CHECK (`assessor_kind` IN ('head_of_institution', 'estate_officer', 'engineer', 'quality_inspector', 'lga_officer', 'contractor', 'community')),
  CONSTRAINT `ck_facility_assessment__usability` CHECK (`usability` IN ('fully_usable', 'usable_minor_repairs', 'usable_major_repairs', 'unsafe_restricted', 'unusable', 'condemned')),
  CONSTRAINT `ck_facility_assessment__structural_risk` CHECK (`structural_risk` IN ('critical', 'high', 'moderate', 'info'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[EST/event/internal] Dated condition and usability assessment of a site, building, room or item of equipment';

CREATE TABLE `maintenance_schedule` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `subject_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `subject_id` BINARY(16) NOT NULL,
  `task` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `task_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `frequency_days` SMALLINT NOT NULL,
  `last_done_on` DATE,
  `next_due_on` DATE NOT NULL,
  `responsible_staff_id` BINARY(16),
  `estimated_cost_minor` BIGINT COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_maintenance_schedule_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_maintenance_schedule_institution_id_next_due_on` (`tenant_id`, `institution_id`, `next_due_on`),
  CONSTRAINT `ck_maintenance_schedule__subject_kind` CHECK (`subject_kind` IN ('site', 'building', 'room', 'asset')),
  CONSTRAINT `ck_maintenance_schedule__task_kind` CHECK (`task_kind` IN ('inspection', 'servicing', 'statutory_test', 'cleaning', 'pest_control', 'roofing', 'plumbing', 'electrical', 'painting', 'generator_service', 'solar_service', 'borehole_service', 'fire_safety', 'replacement', 'other')),
  CONSTRAINT `ck_maintenance_schedule__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[EST/config/internal] Planned preventive maintenance task for a site, building, room or item of equipment (frequency, next due, responsible person)';

CREATE TABLE `property_site` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `site_code` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `institution_id` BINARY(16) NOT NULL,
  `campus_id` BINARY(16),
  `owner` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `title_document` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `title_reference` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'C of O, gazette or survey plan number',
  `area_sqm` DECIMAL(14,2),
  `location` POINT SRID 4326,
  `boundary` JSON COMMENT 'GeoJSON polygon of the surveyed boundary',
  `fenced` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `encroachment` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `acquired_on` DATE,
  `valuation_minor` BIGINT COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin,
  `valued_on` DATE,
  `data_status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_property_site_scope_node_id_site_code` (`tenant_id`, `scope_node_id`, `site_code`),
  KEY `ix_property_site_institution_id` (`tenant_id`, `institution_id`),
  CONSTRAINT `ck_property_site__owner` CHECK (`owner` IN ('federal_government', 'state_government', 'local_government', 'community', 'mission_or_faith', 'private', 'leased')),
  CONSTRAINT `ck_property_site__title_document` CHECK (`title_document` IN ('certificate_of_occupancy', 'right_of_occupancy', 'gazette', 'deed_of_assignment', 'deed_of_gift', 'survey_plan_only', 'customary', 'lease', 'none_or_unknown')),
  CONSTRAINT `ck_property_site__fenced` CHECK (`fenced` IN ('fully_fenced', 'partly_fenced', 'not_fenced', 'unknown')),
  CONSTRAINT `ck_property_site__encroachment` CHECK (`encroachment` IN ('none', 'suspected', 'confirmed', 'in_dispute', 'resolved', 'unknown')),
  CONSTRAINT `ck_property_site__data_status` CHECK (`data_status` IN ('verified', 'illustrative', 'to_confirm')),
  CONSTRAINT `ck_property_site__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[EST/master/internal] Government property site (land) used by an institution — owner, title, area, boundary, fencing, encroachment, valuation';

