ALTER TABLE `imprest` ADD CONSTRAINT `fk_imprest__cost_centre_id` FOREIGN KEY (`tenant_id`, `cost_centre_id`) REFERENCES `cost_centre` (`tenant_id`, `id`);

ALTER TABLE `imprest` ADD CONSTRAINT `fk_imprest__budget_line_id` FOREIGN KEY (`tenant_id`, `budget_line_id`) REFERENCES `budget_line` (`tenant_id`, `id`);

ALTER TABLE `imprest` ADD CONSTRAINT `fk_imprest__commitment_id` FOREIGN KEY (`tenant_id`, `commitment_id`) REFERENCES `budget_commitment` (`tenant_id`, `id`);

